  owner: string,
  /** Repository name (required for labels, assignees, milestones, branches, issue fields, reviewers) */
  repo?: string,
}): Promise<unknown>"},{"path":"tools.github.issue_read","description":"Get information about a specific issue in a GitHub repository.","signature":"tools.github.issue_read({
  /** The number of the issue */
  issue_number: number,
  /**
   * The read operation to perform on a single issue.
   * Options are:
   * 1. get - Get issue details. Also returns best-effort hierarchy flags (`has_parent`, `has_children`); `parent` and `sub_issues_summary` are optional relationship summaries, and `closed_by_pull_requests` summarizes the pull requests configured to close the issue as `total_count` plus up to 5 `references`.
   * 2. get_comments - Get issue comments.
   * 3. get_sub_issues - Get sub-issues (children) of the issue.
   * 4. get_parent - Get the parent issue, if this issue is a sub-issue of another.
   * 5. get_labels - Get labels assigned to the issue.
   */
  method: "get" | "get_comments" | "get_sub_issues" | "get_parent" | "get_labels",
  /** The owner of the repository */
  owner: string,
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /** The name of the repository */
  repo: string,
}): Promise<unknown>"},{"path":"tools.github.get_me","description":"Get details of the authenticated GitHub user. Use this when a request is about the user's own profile for GitHub. Or when information is missing to build other tool calls.","signature":"tools.github.get_me(): Promise<unknown>"},{"path":"tools.github.issue_write","description":"Create a new or update an existing issue in a GitHub repository.","signature":"tools.github.issue_write({
  /** Usernames to assign to this issue */
  assignees?: Array<string>,
  /** Issue body content */
  body?: string,
  /** Issue number that this issue is a duplicate of. Required when state_reason is 'duplicate'. */
  duplicate_of?: number,
